package main

import "fmt"

// canShip loads packages in order, never over capacity, and reports whether that takes at most days.
func canShip(weights []int, capacity, days int) bool {
	used, load := 1, 0
	for _, w := range weights {
		if load+w > capacity {
			used++
			load = 0
		}
		load += w
	}
	return used <= days
}

func main() {
	var n int
	fmt.Scan(&n)
	weights := make([]int, n)
	heaviest, total := 0, 0
	for i := range weights {
		fmt.Scan(&weights[i])
		total += weights[i]
		if weights[i] > heaviest {
			heaviest = weights[i]
		}
	}
	var q int
	fmt.Scan(&q)
	for ; q > 0; q-- {
		var days int
		fmt.Scan(&days)
		lo, hi := heaviest, total
		for lo < hi {
			mid := lo + (hi-lo)/2
			if canShip(weights, mid, days) {
				hi = mid
			} else {
				lo = mid + 1
			}
		}
		fmt.Printf("days %d: capacity %d\n", days, lo)
	}
}

